import{_ as e,o as t,c as i,ag as s}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"接入 MQTT 并生成数据点","description":"配置 Broker、订阅与变量解析，主动生成数据点，并区分消息样例、固定值和持续运行。","frontmatter":{"title":"接入 MQTT 并生成数据点","description":"配置 Broker、订阅与变量解析，主动生成数据点，并区分消息样例、固定值和持续运行。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/mqtt-datapoints.md","filePath":"zh/使用指南/接入MQTT并生成数据点.md"}'),r={name:"zh/guide/mqtt-datapoints.md"};function o(n,a,h,p,l,d){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="接入-mqtt-并生成数据点" tabindex="-1">接入 MQTT 并生成数据点 <a class="header-anchor" href="#接入-mqtt-并生成数据点" aria-label="Permalink to &quot;接入 MQTT 并生成数据点&quot;">​</a></h1><p>入口：<strong>数据中心 → 接入源</strong>。先取得 Broker 地址、协议、端口、认证、证书及获准订阅的 Topic。测试发布必须使用已授权主题，不向真实控制主题随意发消息。</p><h2 id="_1-创建连接并确认订阅" tabindex="-1">1. 创建连接并确认订阅 <a class="header-anchor" href="#_1-创建连接并确认订阅" aria-label="Permalink to &quot;1. 创建连接并确认订阅&quot;">​</a></h2><p>点击“新建连接”，选择 <strong>“MQTT”</strong>。填写协议、主机、端口和必要凭据，按服务要求配置 TLS、Client ID 等选项，再测试和创建。</p><p>打开连接后，使用 <strong>“新建订阅”</strong>，填写名称、Topic、QoS 和说明，保存后在左侧树找回。Topic 通配符会扩大订阅范围，先确认权限和数据量。</p><p>QoS 和重连行为按业务要求安排，不把某个选项理解为整条业务链已经“绝不丢失或重复”。</p><h2 id="_2-查看真实消息再设解析" tabindex="-1">2. 查看真实消息再设解析 <a class="header-anchor" href="#_2-查看真实消息再设解析" aria-label="Permalink to &quot;2. 查看真实消息再设解析&quot;">​</a></h2><p>按页面连接 Broker，使用订阅的 **“查看消息”**检查 Topic、载荷和时间。</p><p>例如练习消息可以是：</p><div class="language-json vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;temperature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>这只是结构样例。没有真实新消息时，可以准备解析配置，但不能据此确认连接和实际数据流正常。</p><h2 id="_3-配置变量并生成点" tabindex="-1">3. 配置变量并生成点 <a class="header-anchor" href="#_3-配置变量并生成点" aria-label="Permalink to &quot;3. 配置变量并生成点&quot;">​</a></h2><p>进入订阅的 **“变量”**区域，添加变量，选择正确类型与解析方式。上面的练习温度可以用数值类型、JSONPath <code>$.temperature</code>，再核对名称、单位和实际解析结果。</p><p>固定值或默认值用于特定配置目的，不证明消息字段已经读通。数组、对象和逐条变量按真实消息结构处理，不套用单一字段规则。</p><p>保存变量后点击 <strong>“生成数据点”</strong>。有选择时核对已选变量；未选择时可能对当前主题全部变量生成或刷新，确认数量与提示后再继续。</p><h2 id="_4-到哪里核对-ai-或手工成果" tabindex="-1">4. 到哪里核对 AI 或手工成果 <a class="header-anchor" href="#_4-到哪里核对-ai-或手工成果" aria-label="Permalink to &quot;4. 到哪里核对 AI 或手工成果&quot;">​</a></h2><ul><li>订阅、Topic：对应 MQTT 连接的左侧订阅树。</li><li>变量、解析规则：打开订阅的“变量”。</li><li>数据点：数据中心 → 数据点，复制完整路径并查看来源。</li><li>页面权限：应用开发 → 数据点 → 调用权限。</li></ul><p>存在订阅不代表已经生成点；生成点也不代表当前有新消息。核对质量、时间和值来源，避免把上次消息或默认值当作实时采样。</p><h2 id="_5-正式使用前" tabindex="-1">5. 正式使用前 <a class="header-anchor" href="#_5-正式使用前" aria-label="Permalink to &quot;5. 正式使用前&quot;">​</a></h2><p>确认正式部署的连接、订阅、运行采集链路与凭据，按需要配置<a href="/induframe-docs/zh/guide/compute-datapoints.html">计算</a>、<a href="/induframe-docs/zh/guide/point-alarms.html">报警</a>和<a href="/induframe-docs/zh/guide/point-history.html">历史存储</a>。</p><p>调试连接、消息查看窗口和正式运行分别确认。删除订阅、批量刷新变量或更改解析前，先检查页面及其他规则引用。</p><p>下一步：<a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a> · <a href="/induframe-docs/zh/guide/access-sources.html">接入源总览</a>。</p>',22)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
